import sys; sys.path.insert(0,'.')
from helpers import *
from scipy.special import erf as serf
D=np.load('base_feats.npz'); y=D['y']; folds=np.load('folds.npy')
c11=D['cls11'].astype(np.float64); m11=D['mean11'].astype(np.float64)
x=c11+2*m11; xc=x-x.mean(1,keepdims=True); n=xc/xc.std(1,keepdims=True)
mu=n.mean(0); sd=n.std(0)+1e-6; Z=(n-mu)/sd; d=768
T=np.eye(8)[y]
gelu=lambda u: 0.5*u*(1+serf(u/np.sqrt(2)))
G=Z@Z.T/d
def feat_cv(fn, lam):
    pred=np.zeros(len(y),int)
    for f in range(5):
        tr=folds!=f; P=fn(G[:,tr]); Ptr=P[tr]; pm=Ptr.mean(0); A=Ptr-pm
        a=np.linalg.solve(A@A.T+lam*np.eye(len(A)),T[tr]-T[tr].mean(0))
        pred[~tr]=np.argmax((P[~tr]-pm)@(A.T@a),1)
    return (pred==y).mean()
def krr_cv(fn, lam):
    pred=np.zeros(len(y),int)
    for f in range(5):
        tr=folds!=f; K=fn(G[np.ix_(tr,tr)])
        a=np.linalg.solve(K+lam*np.eye(len(K)),T[tr]-T[tr].mean(0))
        pred[~tr]=np.argmax(fn(G[np.ix_(~tr,tr)])@a,1)
    return (pred==y).mean()
for beta,theta in [(1,0),(1.5,0),(2,0),(3,0),(2,-1),(3,1)]:
    fn=lambda g,b=beta,t=theta: gelu(b*g-t)
    print('feat',beta,theta,[round(feat_cv(fn,l),4) for l in [0.01,0.03,0.1]],
          '| krr',[round(krr_cv(fn,l),4) for l in [0.01,0.1,1]],flush=True)
